        "import numpy as np\n",
        "import os\n",
        "\n",
        "for case in selected[\"Case\"]:\n",
        "\n",
        "    file_path = os.path.join(ct_folder, case + \"_ct.nii.gz\")\n",
        "    data = loader(file_path)\n",
        "\n",
        "    total = data.numel()\n",
        "\n",
        "    below_min = (data < -1000).sum().item()\n",
        "    above_max = (data > 1000).sum().item()\n",
        "\n",
        "    below_percent = (below_min / total) * 100\n",
        "    above_percent = (above_max / total) * 100\n",
